            int durationDays,
            long startAt,
            long endAt)
        {
            this.title = title;
            this.type = type;
            this.subType = subType;
            this.requiredRank = requiredRank;
            this.createdBy = createdBy;
            this.world = world;
            this.durationDays = durationDays;
