    private CompletableFuture<String> post(
            String baseUrl,
            String functionName,
            String token,
            String json) {
        String base = normalizeBaseUrl(baseUrl);
        Request.Builder builder = new Request.Builder()
                .url(base + "/" + functionName)
                .post(RequestBody.create(JSON, json));

        if (token != null && !token.isEmpty()) {
            builder.addHeader("Authorization", "Bearer " + token);
        }

        Request request = builder.build();

        log.debug("Sending POST to: {}", request.url());
        CompletableFuture<String> future = new CompletableFuture<>();
        httpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException error)
            {
                future.completeExceptionally(error);
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (Response closeableResponse = response)
                {
                    String responseBody = closeableResponse.body() == null
                        ? ""
                        : closeableResponse.body().string();
                    log.debug("Response status: {}", closeableResponse.code());

                    if (!closeableResponse.isSuccessful()) {
                        String retryAfter = closeableResponse.header("Retry-After");
                        String retryMessage = retryAfter == null || retryAfter.isEmpty()
                                ? ""
                                : " Retry after " + retryAfter + " seconds.";
                        future.completeExceptionally(new RuntimeException(
                                "HTTP "
                                        + closeableResponse.code()
                                        + ": "
                                        + errorValue(responseBody)
                                        + retryMessage
                        ));
                        return;
                    }
                    future.complete(responseBody);
                }
                catch (IOException error)
                {
                    future.completeExceptionally(error);
                }
            }
        });
        return future;
    }

    private String normalizeBaseUrl(String value) {
        String base = value == null ? "" : value.trim();

        while (base.endsWith("/")) {
            base = base.substring(0, base.length() - 1);
        }

        if (!base.startsWith("https://")) {
            throw new IllegalArgumentException(
                    "API URL must begin with https://"
            );
        }

        return base;
    }

    private static String escape(String value) {
        if (value == null) {
            return "";
        }

        return value
                .replace("\\", "\\\\")
                .replace("\"", "\\\"")
                .replace("\r", " ")
                .replace("\n", " ");
    }

    private static String stringValue(String json, String key) {
        if (json == null) {
            return "";
        }

        String marker = "\"" + key + "\":\"";
        int start = json.indexOf(marker);

        if (start < 0) {
            return "";
        }

        start += marker.length();
        int end = json.indexOf('"', start);

        return end < 0
                ? ""
                : json.substring(start, end);
    }

    private static int intValue(String json, String key) {
        if (json == null) {
            return 0;
        }

        String marker = "\"" + key + "\":";
        int start = json.indexOf(marker);

        if (start < 0) {
            return 0;
        }

        start += marker.length();

        while (start < json.length()
                && Character.isWhitespace(json.charAt(start))) {
            start++;
        }

        int end = start;

        while (end < json.length()
                && Character.isDigit(json.charAt(end))) {
            end++;
        }

        try {
            return Integer.parseInt(json.substring(start, end));
        } catch (RuntimeException ignored) {
            return 0;
        }
    }

    private static String errorValue(String json) {
        String value = stringValue(json, "error");

        return value.isEmpty()
                ? "Request failed."
                : value;
    }

    private static String friendly(Throwable error) {
        Throwable cause = error;

        while (cause.getCause() != null) {
            cause = cause.getCause();
        }

        if (cause instanceof TimeoutException) {
            return "Connection timed out. Reset Website API URL to its default in the plugin settings, then try a fresh link code.";
        }

        String message = cause.getMessage();

        return message == null || message.isEmpty()
                ? "Network request failed."
                : message;
    }

